//! Production byte decoder composed with the real recorder/App/Core controller.
//! Generated bytes and virtual observations only, not terminal or Audio E2E proof.
use std::{cell::RefCell, rc::Rc, time::Duration};

use riotbox_core::{
    action::{ActionCommand, ActionStatus, CommitBoundary, LiveRecordingDuration},
    persistence::load_session_json,
};

use super::super::execute_with_control_and_input;
use super::{Case, Event, fixture};
use crate::cli::{
    live_master_recording::terminal_input::generated_byte_input,
    model::{LaunchMode, LiveRecordingInputMode},
};

#[test]
fn byte_adapter_suppresses_csi_fill_then_commits_only_plain_fill_before_completion() {
    let (_owner, mut launch, mut state, mut control) =
        fixture(Case::Clean, LiveRecordingDuration::TwoBars, false);
    let LaunchMode::LiveMasterRecordingExecute { input_mode, .. } = &mut launch.mode else {
        unreachable!();
    };
    *input_mode = LiveRecordingInputMode::TerminalFill;

    let attempts = Rc::new(RefCell::new(Vec::new()));
    // CSI's final `f` is not a performer Fill. The following plain `f` is.
    // A cancel at the exact completion boundary must never reach the reader.
    let scheduled = b"\x1b[1;2ff"
        .iter()
        .enumerate()
        .map(|(index, byte)| (Duration::from_millis(500 + index as u64 * 10), *byte))
        .chain([(Duration::from_secs(6), b'q')])
        .collect();
    let mut input =
        generated_byte_input(scheduled, Rc::clone(&control.elapsed), Rc::clone(&attempts));
    let summary =
        execute_with_control_and_input(&launch, &mut state, &mut control, &mut input).unwrap();

    assert_eq!(summary["ready"], true, "{summary}");
    assert_eq!(summary["runtime_stopped"], true);
    assert_eq!(control.elapsed.get(), Duration::from_secs(6));
    assert_eq!(
        *control.events.borrow(),
        [Event::Begin, Event::Stop, Event::Finish]
    );
    let expected_attempts = (0_u64..600)
        .map(|index| Duration::from_millis(index * 10))
        .collect::<Vec<_>>();
    assert_eq!(
        *attempts.borrow(),
        expected_attempts,
        "one byte attempt per Pending iteration; none after recognized completion"
    );

    let fills = state
        .session
        .action_log
        .actions
        .iter()
        .filter(|action| action.command == ActionCommand::Tr909FillNext)
        .collect::<Vec<_>>();
    assert_eq!(fills.len(), 1, "CSI must not enqueue a second Fill");
    let fill = fills[0];
    assert_eq!(fill.status, ActionStatus::Committed);
    assert!(fill.result.as_ref().unwrap().accepted);
    assert_eq!(
        fill.requested_at, 1_560,
        "the accepted action must belong to plain f, not the earlier CSI final f"
    );
    assert_eq!(fill.committed_at, Some(3_000));
    let record = state
        .session
        .action_log
        .commit_records
        .iter()
        .find(|record| record.action_id == fill.id)
        .unwrap();
    assert_eq!(record.boundary.kind, CommitBoundary::Bar);
    assert_eq!(record.boundary.beat_index, 4);
    assert!(state.queue.pending_actions().is_empty());

    let report = &summary["terminal_input"];
    assert_eq!(report["queued_action_ids"], serde_json::json!([fill.id]));
    assert_eq!(
        report["core_committed_action_ids"],
        serde_json::json!([fill.id])
    );
    assert_eq!(report["not_committed_action_ids"], serde_json::json!([]));
    assert_eq!(report["ignored_event_count"], 1);
    assert_eq!(report["render_delivery"], "not_qualified");

    let saved = load_session_json(&state.files.as_ref().unwrap().session_path).unwrap();
    let saved_fills = saved
        .action_log
        .actions
        .iter()
        .filter(|action| action.command == ActionCommand::Tr909FillNext)
        .collect::<Vec<_>>();
    assert_eq!(saved_fills, fills);
    assert_eq!(
        saved
            .action_log
            .commit_records
            .iter()
            .find(|saved_record| saved_record.action_id == fill.id),
        Some(record)
    );
    assert_eq!(saved.export_receipts, state.session.export_receipts);
    assert_eq!(saved.export_receipts.len(), 1);
    assert!(saved.export_receipts[0].live_recording_runtime_master_ready());
}
